package com.brightloop.invoice.service;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.brightloop.common.enums.InvoiceStatus;
import com.brightloop.common.exception.*;
import com.brightloop.customer.service.CustomerService;
import com.brightloop.discount.service.DiscountService;
import com.brightloop.invoice.dto.*;
import com.brightloop.invoice.entity.*;
import com.brightloop.invoice.repository.InvoiceRepository;
import com.brightloop.notification.NotificationService;
import com.brightloop.subscription.entity.Subscription;
import com.brightloop.subscription.entity.SubscriptionItem;
import com.brightloop.subscription.repository.SubscriptionRepository;
import com.brightloop.tax.service.TaxService;
import org.springframework.data.domain.*;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.*;
import java.time.*;
import java.util.*;
import java.util.stream.Collectors;

@Service public class InvoiceService{
 private final InvoiceRepository invoices;private final SubscriptionRepository subscriptions;private final CustomerService customers;private final TaxService taxes;private final DiscountService discounts;private final ObjectMapper json;private final NotificationService notifications;
 public InvoiceService(InvoiceRepository i,SubscriptionRepository s,CustomerService c,TaxService t,DiscountService d,ObjectMapper j,NotificationService n){invoices=i;subscriptions=s;customers=c;taxes=t;discounts=d;json=j;notifications=n;}
 @Transactional(readOnly=true) public Page<InvoiceResponse> list(String email,boolean privileged,Pageable page){return (privileged?invoices.findAllByOrderByInvoiceDateDesc(page):invoices.findByCustomer_User_EmailOrderByInvoiceDateDesc(email,page)).map(this::map);}
 @Transactional(readOnly=true) public Page<InvoiceResponse> overdue(String email,boolean privileged,Pageable page){Page<Invoice> rows=privileged?invoices.findOverdue(LocalDate.now(),List.of(InvoiceStatus.CANCELLED,InvoiceStatus.PAID),page):invoices.findOverdueForCustomer(email,LocalDate.now(),List.of(InvoiceStatus.CANCELLED,InvoiceStatus.PAID),page);return rows.map(this::map);}
 @Transactional(readOnly=true) public InvoiceResponse get(UUID id,String email,boolean privileged){Invoice i=detail(id);if(!privileged&&!i.getCustomerEmail().equalsIgnoreCase(email))throw new AccessDeniedException("You cannot access this invoice");return map(i);}
 @Transactional public InvoiceResponse generate(UUID subscriptionId,LocalDate requestedStart){Subscription s=subscriptions.findLocked(subscriptionId).orElseThrow(()->new ResourceNotFoundException("Subscription not found"));LocalDate start=requestedStart==null?s.getNextBillingDate():requestedStart;if(start==null)throw new ConflictException("Subscription has no scheduled billing date");var previous=invoices.findBySubscription_IdAndPeriodStart(subscriptionId,start);if(previous.isPresent())return map(detail(previous.get().getId()));if(!start.equals(s.getNextBillingDate())||start.isAfter(LocalDate.now()))throw new ConflictException("Subscription is not due for billing on that date");LocalDate end=s.getExpiryDate()==null?next(start,s).minusDays(1):min(next(start,s).minusDays(1),s.getExpiryDate());LocalDate today=LocalDate.now();String number="INV-"+UUID.randomUUID().toString().substring(0,12).toUpperCase(Locale.ROOT);BigDecimal subtotal=s.getItems().stream().map(SubscriptionItem::getLineTotal).reduce(BigDecimal.ZERO,BigDecimal::add);Map<UUID,BigDecimal> productBases=productBases(s.getItems());int quantity=s.getItems().stream().mapToInt(SubscriptionItem::getQuantity).sum();var discount=discounts.applyBest(number,subtotal,productBases,quantity,today);List<BigDecimal> allocated=allocateDiscount(s.getItems(),discount);BigDecimal totalTax=BigDecimal.ZERO,addedTax=BigDecimal.ZERO;List<InvoiceItem> itemList=new ArrayList<>();for(int n=0;n<s.getItems().size();n++){SubscriptionItem source=s.getItems().get(n);BigDecimal lineSubtotal=source.getLineTotal(),lineDiscount=allocated.get(n),taxBase=lineSubtotal.subtract(lineDiscount);TaxService.TaxCalculation tax;try{tax=taxes.calculate(UUID.fromString(source.getProductId()),taxBase,today);}catch(IllegalArgumentException e){tax=new TaxService.TaxCalculation(BigDecimal.ZERO,BigDecimal.ZERO,List.of());}totalTax=totalTax.add(tax.amount());addedTax=addedTax.add(tax.addedAmount());BigDecimal lineTotal=taxBase.add(tax.addedAmount());itemList.add(new InvoiceItem(source.getProductId(),source.getProductName(),source.getVariantName(),source.getQuantity(),source.getUnitPrice(),lineDiscount,tax.amount(),lineTotal,toJson(tax.rules())));}BigDecimal total=subtotal.subtract(discount.amount()).add(addedTax);LocalDate due=today.plusDays(paymentDays(s.getPaymentTerms()));Invoice invoice=new Invoice(number,s,start,end,today,due,subtotal,discount.amount(),totalTax,total,discount.name());itemList.forEach(invoice::addItem);Invoice saved=invoices.saveAndFlush(invoice);discounts.linkInvoice(number,saved.getId());s.completeBillingCycle();notifications.enqueue(saved.getCustomerEmail(),"INVOICE","Invoice "+saved.getNumber()+" generated","Invoice total: "+saved.getTotalAmount()+". Due date: "+saved.getDueDate());return map(saved);}
 @Transactional public InvoiceResponse confirm(UUID id){Invoice i=invoices.findLocked(id).orElseThrow(()->new ResourceNotFoundException("Invoice not found"));try{i.confirm();}catch(IllegalStateException e){throw new ConflictException(e.getMessage());}return map(i);}
 @Transactional public void cancel(UUID id){Invoice i=invoices.findLocked(id).orElseThrow(()->new ResourceNotFoundException("Invoice not found"));try{i.cancel();}catch(IllegalStateException e){throw new ConflictException(e.getMessage());}}
 @Transactional public Invoice allocatePayment(UUID invoiceId,BigDecimal amount,UUID expectedCustomerId){Invoice i=invoices.findLocked(invoiceId).orElseThrow(()->new ResourceNotFoundException("Invoice not found"));if(!i.getCustomer().getId().equals(expectedCustomerId))throw new ConflictException("Payment allocations must belong to one customer");if(i.getStatus()==InvoiceStatus.DRAFT)throw new ConflictException("Confirm invoice before recording payment");try{i.applyPayment(amount);}catch(IllegalStateException e){throw new ConflictException(e.getMessage());}return i;}
 @Transactional(readOnly=true) public InvoiceResponse paymentTarget(UUID id){return map(detail(id));}
 @Transactional public int markOverdue(int size){List<Invoice> rows=invoices.findByStatusInAndDueDateBeforeAndOutstandingAmountGreaterThan(List.of(InvoiceStatus.CONFIRMED,InvoiceStatus.PARTIALLY_PAID),LocalDate.now(),BigDecimal.ZERO,PageRequest.of(0,size));rows.forEach(i->i.markOverdue(LocalDate.now()));return rows.size();}
 private Invoice detail(UUID id){return invoices.findDetailedById(id).orElseThrow(()->new ResourceNotFoundException("Invoice not found"));}
 private InvoiceResponse map(Invoice i){return new InvoiceResponse(i.getId(),i.getNumber(),i.getCustomer().getId(),i.getSubscription().getId(),i.getPeriodStart(),i.getPeriodEnd(),i.getInvoiceDate(),i.getDueDate(),i.getCustomerName(),i.getCustomerEmail(),i.getCompanyName(),i.getCustomerPhone(),i.getCustomerAddress(),i.getSubtotal(),i.getDiscountAmount(),i.getTaxAmount(),i.getTotalAmount(),i.getPaidAmount(),i.getOutstandingAmount(),i.getStatus(),i.getDiscountName(),i.getItems().stream().map(x->new InvoiceResponse.Item(x.getId(),x.getProductId(),x.getProductName(),x.getVariantName(),x.getQuantity(),x.getUnitPrice(),x.getSubtotal(),x.getDiscountAmount(),x.getTaxAmount(),x.getTotalAmount(),x.getTaxDetailsJson())).toList());}
 private Map<UUID,BigDecimal> productBases(List<SubscriptionItem> items){Map<UUID,BigDecimal> map=new HashMap<>();for(var i:items)try{UUID id=UUID.fromString(i.getProductId());map.merge(id,i.getLineTotal(),BigDecimal::add);}catch(Exception ignored){}return map;}
 private List<BigDecimal> allocateDiscount(List<SubscriptionItem> items,DiscountService.DiscountApplication discount){List<BigDecimal> result=new ArrayList<>(Collections.nCopies(items.size(),BigDecimal.ZERO));if(discount.amount().signum()==0)return result;List<Integer> eligible=new ArrayList<>();BigDecimal base=BigDecimal.ZERO;for(int n=0;n<items.size();n++){var line=items.get(n);boolean apply=discount.applicableProductIds().isEmpty();try{apply=apply||discount.applicableProductIds().contains(UUID.fromString(line.getProductId()));}catch(Exception ignored){}if(apply){eligible.add(n);base=base.add(line.getLineTotal());}}BigDecimal remaining=discount.amount();for(int j=0;j<eligible.size();j++){int n=eligible.get(j);BigDecimal amount=j==eligible.size()-1?remaining:discount.amount().multiply(items.get(n).getLineTotal()).divide(base,4,RoundingMode.HALF_UP);result.set(n,amount);remaining=remaining.subtract(amount);}return result;}
 private String toJson(Object value){try{return json.writeValueAsString(value);}catch(JsonProcessingException e){throw new IllegalStateException("Could not snapshot tax details",e);}}
 private LocalDate next(LocalDate start,Subscription s){return switch(s.getPlan().getBillingFrequency()){case DAILY->start.plusDays(1);case WEEKLY->start.plusWeeks(1);case MONTHLY->start.plusMonths(1);case YEARLY->start.plusYears(1);};}
 private LocalDate min(LocalDate a,LocalDate b){return a.isBefore(b)?a:b;}
 private int paymentDays(String terms){if(terms==null)return 14;var m=java.util.regex.Pattern.compile("(?i)NET[_ -]?(\\d{1,3})").matcher(terms);if(!m.matches())return 14;return Math.min(365,Integer.parseInt(m.group(1)));}
}
